 private void setupBilling(){
 billing=BillingClient.newBuilder(this).setListener((result,list)->runOnUiThread(()->{purchaseBusy=false;if(result.getResponseCode()==BillingClient.BillingResponseCode.OK&&list!=null){for(Purchase p:list)deliver(p);}else if(result.getResponseCode()!=BillingClient.BillingResponseCode.USER_CANCELED)notice(result.getDebugMessage());})).enablePendingPurchases(PendingPurchasesParams.newBuilder().enableOneTimeProducts().build()).enableAutoServiceReconnection().build();
 billing.startConnection(new BillingClientStateListener(){public void onBillingServiceDisconnected(){} public void onBillingSetupFinished(BillingResult result){if(result.getResponseCode()==BillingClient.BillingResponseCode.OK){runOnUiThread(()->{loadProducts();restore(false);});}}});
 }
