 private void buy(String id){if(purchaseBusy)return;if("fuel_refill".equals(id)&&"UNAVAILABLE".equals(price(id))){notice("Fuel Refill: "+fuelDiagnostic);if(billing!=null&&billing.isReady())loadProducts();return;}if(billing==null||!billing.isReady()||!products.containsKey(id)){notice("Google Play product unavailable. Please try again.");if(billing!=null&&billing.isReady())loadProducts();return;}ProductDetails d=products.get(id);ProductDetails.OneTimePurchaseOfferDetails offer=d.getOneTimePurchaseOfferDetails();if(offer==null){notice("Price unavailable");return;}BillingFlowParams.ProductDetailsParams.Builder item=BillingFlowParams.ProductDetailsParams.newBuilder().setProductDetails(d);if(offer.getOfferToken()!=null&&!offer.getOfferToken().isEmpty())item.setOfferToken(offer.getOfferToken());purchaseBusy=true;BillingResult result=billing.launchBillingFlow(this,BillingFlowParams.newBuilder().setProductDetailsParamsList(Collections.singletonList(item.build())).build());if(result.getResponseCode()!=BillingClient.BillingResponseCode.OK){purchaseBusy=false;notice(result.getDebugMessage());}}
 private void restore(boolean manual){if(billing==null||!billing.isReady()){if(manual)notice("Google Play unavailable");return;}billing.queryPurchasesAsync(QueryPurchasesParams.newBuilder().setProductType(BillingClient.ProductType.INAPP).build(),(result,list)->runOnUiThread(()->{if(result.getResponseCode()!=BillingClient.BillingResponseCode.OK)return;for(Purchase p:list)deliver(p);if(manual)notice("Purchases checked");}));}
 private void deliver(Purchase purchase){
 if(game==null||purchase.getPurchaseState()!=Purchase.PurchaseState.PURCHASED||purchase.getProducts().size()!=1)return;
 String id=purchase.getProducts().get(0),token=purchase.getPurchaseToken(),key="billingGrant:"+token;
 int ci=Arrays.asList(creditIds).indexOf(id),si=Arrays.asList(shipIds).indexOf(id);
 boolean permanent=id.equals("skyrocket_pro")||si>=0, fuelItem=id.equals("fuel_refill"), marathonItem=id.matches("marathon_continue_[1-7]");
 if(!permanent&&ci<0&&!fuelItem&&!marathonItem)return;
 if(!processing.add(token))return;
 android.content.SharedPreferences prefs=game.prefs;
 if(permanent){android.content.SharedPreferences.Editor ed=prefs.edit();if(si>=0)ed.putBoolean("owned"+(si+7),true);else ed.putBoolean("verifiedPro",true);if(!ed.commit()){processing.remove(token);return;}if(id.equals("skyrocket_pro"))failureAd=null;if(purchase.isAcknowledged()){processing.remove(token);return;}billing.acknowledgePurchase(AcknowledgePurchaseParams.newBuilder().setPurchaseToken(token).build(),result->runOnUiThread(()->processing.remove(token)));return;}
 if(!prefs.getBoolean(key,false)){
 android.content.SharedPreferences.Editor ed=prefs.edit().putBoolean(key,true);
 int newCredits=game.credits;
 if(ci>=0){newCredits=(int)Math.min(Integer.MAX_VALUE,(long)game.credits+new int[]{1000,5000,15000}[ci]);ed.putInt("credits",newCredits).putInt("coinHighScore",Math.max(game.coinHighScore(),newCredits));}
 if(fuelItem)ed.putInt("paidFuel",prefs.getInt("paidFuel",0)+1);
 if(marathonItem)ed.putInt("paid:"+id,prefs.getInt("paid:"+id,0)+1);
 if(!ed.commit()){processing.remove(token);return;}game.credits=newCredits;
 }
 billing.consumeAsync(ConsumeParams.newBuilder().setPurchaseToken(token).build(),(result,t)->runOnUiThread(()->{processing.remove(token);if(result.getResponseCode()==BillingClient.BillingResponseCode.OK){if(fuelItem)game.useFuel();if(marathonItem)game.useContinue(id);}}));
 }
